{
  "findings": [
    {
      "check_id": "CKV_AZURE_44",
      "title": "Storage Account is not using the latest version of TLS encryption",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account is configured to use TLS 1.0, which is an outdated version with known vulnerabilities."
    },
    {
      "check_id": "AVD-AZU-0011",
      "title": "Storage account uses an insecure TLS version",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "CRITICAL",
      "explanation": "The TLS version being used is outdated and has known vulnerabilities."
    },
    {
      "check_id": "CKV2_AZURE_47",
      "title": "Storage account is configured with blob anonymous access",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account's blob properties do not explicitly disable anonymous access, potentially allowing unauthorized access to blobs."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"media_storage\" {\n  name                     = \"corpmediastorage${random_string.storage_suffix.result}\"\n  resource_group_name      = azurerm_resource_group.corporate_media_streaming.name\n  location                 = azurerm_resource_group.corporate_media_streaming.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"GRS\"\n  enable_https_traffic_only = true\n  min_tls_version = \"TLS1_2\"\n  blob_properties {\n    versioning_enabled = true\n    container_delete_retention_policy {\n      days = 7\n    }\n    delete_retention_policy {\n      days = 7\n    }\n    allow_blob_public_access = false\n  }\n}",
  "fix_summary": "Updated the storage account to use the latest TLS version (TLS 1.2), enabled HTTPS traffic only, and disabled blob public access to prevent unauthorized access."
}
